using System;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using SplifyWin;
namespace Mcrf.Wpf {public sealed partial class MainWindow {
 System.Windows.Shapes.Path ManagementActionIcon(string kind){return new System.Windows.Shapes.Path{Data=System.Windows.Media.Geometry.Parse(kind=="dns"?"M12,2 A10,10 0 1 0 12,22 A10,10 0 1 0 12,2 M2,12 H22 M12,2 C5,6 5,18 12,22 M12,2 C19,6 19,18 12,22":"M7,6 H17 C21,6 23,18 20,19 L16,15 H8 L4,19 C1,18 3,6 7,6 Z M6,11 H12 M9,8 V14 M16,10 V11 M19,12 V13"),Width=16,Height=16,Stretch=System.Windows.Media.Stretch.Uniform,Stroke=Brush(CompactPrimary),StrokeThickness=1.6,StrokeStartLineCap=System.Windows.Media.PenLineCap.Round,StrokeEndLineCap=System.Windows.Media.PenLineCap.Round};}
 Grid CompactButtonPair(Button left,Button right){foreach(var button in new[]{left,right}){StyleCompactButton(button);button.MinWidth=0;button.FontSize=12;button.MinHeight=36;button.Height=36;button.Padding=new Thickness(6);}var row=new Grid{Margin=new Thickness(0,0,0,8)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition());left.Margin=new Thickness(0,0,4,0);right.Margin=new Thickness(4,0,0,0);Grid.SetColumn(right,1);row.Children.Add(left);row.Children.Add(right);return row;}
 void CompactRuleTextButton(Button button){button.Name=String.IsNullOrEmpty(button.Name)?"compactRuleAction":button.Name;if(button.Tag==null)button.Tag="CompactKeepStyle";button.ClearValue(Control.BackgroundProperty);button.ClearValue(Control.BorderBrushProperty);button.ClearValue(Control.BorderThicknessProperty);button.Style=(Style)FindResource("CompactIconAction");button.MinWidth=0;button.MinHeight=28;button.Height=28;button.Width=26;button.HorizontalAlignment=HorizontalAlignment.Center;button.VerticalAlignment=VerticalAlignment.Center;button.Padding=new Thickness(3);button.Margin=new Thickness(0);button.FontSize=10;}
 Button CompactRuleIcon(string icon,string label,Func<Task> action){var button=IconButton(icon,label,action);button.Style=(Style)FindResource("CompactIconAction");button.MinWidth=0;button.MinHeight=28;button.Width=26;button.Height=28;button.HorizontalAlignment=HorizontalAlignment.Center;button.Margin=new Thickness(0);button.Padding=new Thickness(3);return button;}
 void OpenGlobalNetworkDialog(){var window=Dialog("DNS & hosts",420,620);window.Name="globalNetworkWindow";window.MaxHeight=window.Height;window.SizeToContent=SizeToContent.Height;var layout=new DockPanel{Margin=new Thickness(16,8,16,16)};var close=Button("Готово",()=>window.Close());close.Name="globalNetworkClose";DockPanel.SetDock(close,Dock.Bottom);layout.Children.Add(close);var content=new StackPanel{Name="globalNetworkFields"};content.Children.Add(GlobalDnsRow());content.Children.Add(RoutingHostsControls());CompactNormalizeAdvanced(content);layout.Children.Add(new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});window.Content=layout;window.ShowDialog();}
 async Task SaveRouteGame(string id,bool tcp,bool udp){var currentRoute=CurrentSavedRoute(id);if(currentRoute.Target!="zapret")throw new InvalidOperationException("Фильтр TCP/UDP доступен для правил Zapret.");var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();var proposed=serializer.Deserialize<RouteList>(serializer.Serialize(currentRoute));proposed.GameFilterTcp=tcp;proposed.GameFilterUdp=udp;if(proposed.Enabled)ZapretRoutes.Validate(proposed,session.State.ZapretProfiles);await ChangeSavedRoute(id,r=>{r.GameFilterTcp=tcp;r.GameFilterUdp=udp;},false);}
 void OpenRouteGameDialog(string id){var route=CurrentSavedRoute(id);var window=Dialog("Game · "+route.Name,400,360);window.Name="routeGameWindow";window.MaxHeight=window.Height;window.SizeToContent=SizeToContent.Height;var panel=new StackPanel{Margin=new Thickness(16,8,16,16)};bool available=route.Target=="zapret",saving=false;panel.Children.Add(Text(available?"Какие протоколы обрабатывать профилем Zapret для этого правила.":"TCP/UDP-фильтр применяется только к правилам Zapret.",12));var tcp=new CheckBox{Name="routeGameTcp",Content="TCP",Style=(Style)FindResource("LabeledPacketCheck"),IsChecked=route.GameTcpEnabled,Margin=new Thickness(0,4,0,10),IsEnabled=available};var udp=new CheckBox{Name="routeGameUdp",Content="UDP",Style=(Style)FindResource("LabeledPacketCheck"),IsChecked=route.GameUdpEnabled,Margin=new Thickness(0,0,0,10),IsEnabled=available};panel.Children.Add(tcp);panel.Children.Add(udp);var feedback=Text("",11);feedback.Name="routeGameFeedback";feedback.Visibility=Visibility.Collapsed;panel.Children.Add(feedback);Button save=null,cancel=null;save=Button("Применить",async()=>{if(saving)return;saving=true;save.IsEnabled=cancel.IsEnabled=false;try{await SaveRouteGame(id,tcp.IsChecked==true,udp.IsChecked==true);saving=false;window.Close();}catch(Exception ex){feedback.Text=FailureExplanations.UserMessage(JournalStyle.Redact(ex.Message));feedback.Visibility=Visibility.Visible;}finally{saving=false;save.IsEnabled=available;cancel.IsEnabled=true;}});save.Name="routeGameApply";save.IsEnabled=available;cancel=Button("Отмена",()=>window.Close());panel.Children.Add(save);panel.Children.Add(cancel);window.Closing+=(s,e)=>{if(saving)e.Cancel=true;};window.Content=panel;window.ShowDialog();}
}}
